function piBookingEnsureDisplay() {
  if (process.env.DISPLAY) return;
  try {
    const { spawn, spawnSync } = require('child_process');
    const child = spawn('Xvfb', [':99', '-screen', '0', '1920x1080x24', '-ac'], { detached: true, stdio: 'ignore' });
    child.on('error', function () {});
    child.unref();
    process.env.DISPLAY = ':99';
    spawnSync('sleep', ['0.5']);
  } catch (eXvfb) {}
}
async function piBookingLaunchBrowser(pw) {
  piBookingEnsureDisplay();
  const args = ['--disable-blink-features=AutomationControlled', '--disable-dev-shm-usage', '--no-sandbox', '--disable-infobars', '--window-size=1440,900'];
  const proxy = process.env.PLAYWRIGHT_PROXY_SERVER || process.env.HTTPS_PROXY || process.env.HTTP_PROXY || '';
  const opts = { headless: false, args: args, ignoreDefaultArgs: ['--enable-automation'] };
  if (proxy) opts.proxy = { server: proxy };
  try {
    return await pw.chromium.launch(Object.assign({}, opts, { channel: 'chrome' }));
  } catch (eChrome) {
