async function piBookingHumanClick(page, x, y) {
  await page.mouse.move(Math.max(8, Math.round(x * 0.25)), Math.max(8, Math.round(y * 0.35)), { steps: 8 });
  await page.waitForTimeout(70);
  await page.mouse.move(x, y, { steps: 14 });
  await page.waitForTimeout(80);
  await page.mouse.click(x, y, { delay: 70 });
  await page.waitForTimeout(900);
  try {
    await page.locator('input[type="password"]:not(#hidden-password):not([aria-hidden="true"])').first().waitFor({ state: 'visible', timeout: 6000 });
  } catch (ePass) {}
}
async function piBookingHumanType(page, text) {
  const hiddenPass = 'input[type="password"]:not(#hidden-password):not([aria-hidden="true"])';
  const realPass = page.locator(hiddenPass).first();
  const user = page.locator('#loginname, input[name="loginname"]').first();
  let target = null;
  if (await realPass.count()) {
    const box = await realPass.boundingBox().catch(function () { return null; });
    if (box && box.height > 8 && box.width > 40) target = realPass;
  }
  if (!target && await user.count()) target = user;
  if (target) {
    try { await target.focus({ timeout: 4000 }); }
    catch (eFocus) { await target.click({ force: true, timeout: 4000 }); }
    await page.waitForTimeout(150);
    await page.keyboard.type(text, { delay: 95 });
    return;
  }
  await page.keyboard.type(text, { delay: 95 });
}

